#!/usr/bin/env bash\nset -euo pipefail\n\nif [[ $# -ne 1 ]]; then\n  echo "Usage: $0 <commit-message-file>"\n  exit 1\nfi\n\nmsg_file="$1"\nif [[ ! -f "$msg_file" ]]; then\n  echo "File not found: $msg_file"\n  exit 1\nfi\n\nfirst_line=$(head -n1 "$msg_file")\n\n# 1. Subject line length (≤ 50)\nif (( ${#first_line} > 50 )); then\n  echo "Error: Subject line exceeds 50 characters."\n  exit 1\nfi\n\n# 2. Conventional Commits format\nif ! grep -E -q '^(feat|fix|docs|style|refactor|test|chore)(\([^\)]+\))?: .+' <<<"$first_line"; then\n  echo "Error: Subject line does not follow Conventional Commits format."\n  exit 1\nfi\n\n# 3. Body line length (≤ 72) – ignore empty lines\ntail -n +2 "$msg_file" | while IFS= read -r line; do\n  [[ -z "$line" ]] && continue\n  if (( ${#line} > 72 )); then\n    echo "Error: Body line exceeds 72 characters: $line"\n    exit 1\n  fi\n done\n\necho "Commit message looks good."\nexit 0\n
